# ----- lib/fs.sh -----

require_root() {
  local action="${1:-}"
  [[ ${EUID:-$(id -u)} -eq 0 ]] || error "$(t error.root_required "$0" "$action")"
}

require_command() {
  local command_name="$1"
  command -v "$command_name" >/dev/null 2>&1 || error "$(t error.command_required "$command_name")"
}

is_safe_path() {
  local path="${1:-}"
  [[ -n "$path" && "$path" != "/" && "$path" != "." ]]
}

require_safe_path() {
  local name="$1"
  local path="$2"
  is_safe_path "$path" || error "$(t error.unsafe_path "$name" "${path:-empty}")"
}

safe_rm_dir() {
  local path="$1"
  local name="${2:-path}"
  require_safe_path "$name" "$path"
  [[ -d "$path" ]] && rm -rf "$path"
}

# ----- lib/lock.sh -----

acquire_lock() {
  local lock_file="${1:-${LOCK_FILE:-}}"
  [[ -n "$lock_file" ]] || return 0
  mkdir -p "$(dirname "$lock_file")"
  exec 9>"$lock_file"
  flock -n 9 || error "$(t error.lock_failed "$lock_file")"
  trap 'release_lock' EXIT
}

release_lock() {
  flock -u 9 2>/dev/null || true
  exec 9>&- 2>/dev/null || true
}

# ----- lib/config.sh -----

sanitize_conf_val() {
  local value="${1%%$'\n'*}"
  value="${value//\"/}"
  echo "$value"
}

load_config_file() {
  local conf_file="$1"
  shift
  local -a allowed_keys=("$@")
  [[ -f "$conf_file" ]] || return 0

  if command -v stat >/dev/null 2>&1; then
    local owner mode
    owner="$(stat -c '%U' "$conf_file" 2>/dev/null || echo root)"
    mode="$(stat -c '%a' "$conf_file" 2>/dev/null || echo 600)"
    [[ "$owner" == "root" ]] || error "$(t error.config_owner "$conf_file")"
    [[ "$mode" == "600" || "$mode" == "400" ]] || error "$(t error.config_permission "$conf_file")"
  fi

  local line key value allowed
  while IFS= read -r line || [[ -n "$line" ]]; do
    [[ -z "$line" || "$line" == \#* || "$line" != *=* ]] && continue
    key="${line%%=*}"
    value="${line#*=}"
    allowed=false
    local allowed_key
    for allowed_key in "${allowed_keys[@]}"; do
      if [[ "$key" == "$allowed_key" ]]; then
        allowed=true
        break
      fi
    done
    $allowed || continue
    [[ "$key" =~ ^[A-Z_][A-Z0-9_]*$ ]] || continue
    printf -v "$key" '%s' "$value"
  done < "$conf_file"
}

write_config_file() {
  local conf_file="$1"
  shift
  local tmp_file
  tmp_file="$(mktemp "${conf_file}.tmp.XXXXXX")"
  chmod 600 "$tmp_file"
  local key value
  for key in "$@"; do
    value="$(sanitize_conf_val "${!key:-}")"
    printf '%s=%s\n' "$key" "$value" >> "$tmp_file"
  done
  chown root:root "$tmp_file" 2>/dev/null || true
  mv "$tmp_file" "$conf_file"
}

# ----- lib/service.sh -----

wait_for_service() {
  local service_name="$1"
  local timeout="${2:-20}"
  local elapsed=0
  while (( elapsed < timeout )); do
    if systemctl is-active --quiet "$service_name"; then
      return 0
    fi
    if systemctl is-failed --quiet "$service_name"; then
      return 1
    fi
    sleep 1
    elapsed=$((elapsed + 1))
  done
  return 1
}

service_status_label() {
  local service_name="$1"
  if systemctl is-active --quiet "$service_name" 2>/dev/null; then
    t status.active
  elif systemctl list-unit-files "$service_name.service" >/dev/null 2>&1; then
    t status.inactive
  else
    t status.unknown
  fi
}

# ----- lib/network.sh -----

check_connectivity_urls() {
  local url
  for url in "$@"; do
    if curl -fsI --connect-timeout 5 --max-time 10 "$url" >/dev/null 2>&1; then
      return 0
    fi
  done
  return 1
}

